-- Independent Geocontrol Hub schema. Never apply to traccar or traccar_dev.
CREATE TABLE IF NOT EXISTS hub_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,role ENUM('owner','admin','editor','viewer') NOT NULL DEFAULT 'viewer',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hub_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(120) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,summary TEXT,status ENUM('planning','active','paused','completed') NOT NULL DEFAULT 'planning',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hub_phases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,description TEXT,position INT NOT NULL DEFAULT 0,status ENUM('pending','active','completed') NOT NULL DEFAULT 'pending',FOREIGN KEY(project_id) REFERENCES hub_projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS hub_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,phase_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,description TEXT,status ENUM('todo','in_progress','blocked','done') NOT NULL DEFAULT 'todo',priority ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal',due_date DATE NULL,archived_at TIMESTAMP NULL DEFAULT NULL,archived_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_hub_tasks_project_archived(project_id,archived_at,id),FOREIGN KEY(project_id) REFERENCES hub_projects(id) ON DELETE CASCADE,FOREIGN KEY(phase_id) REFERENCES hub_phases(id) ON DELETE SET NULL,FOREIGN KEY(archived_by) REFERENCES hub_users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS hub_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES hub_projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS hub_audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_created(created_at),FOREIGN KEY(actor_id) REFERENCES hub_users(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS hub_login_attempts (attempt_key CHAR(64) PRIMARY KEY,failures INT UNSIGNED NOT NULL DEFAULT 0,window_started TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
